const alert = $json;

if (
  !alert.id ||
  !alert.source_id ||
  !alert.lease_token ||
  !alert.source_system
) {
  throw new Error("Missing reliability alert ownership");
}

const content = [
  "🚨 TRACEOPS AUTOMATION RELIABILITY ALERT",
  "",
  `System: ${alert.source_system}`,
  `Problem: ${alert.problem_status}`,
  `Source ID: ${alert.source_id}`,
  `Monitoring Alert ID: ${alert.id}`,
  "",
  "Action required: Investigate the source record.",
  "Check the external provider before retrying.",
  "Never automatically resend uncertain financial or customer notifications."
].join("\n");

return {
  json: {
    ...alert,
    discord_message: content
  }
};

